"""Brief writer agent: a sourced brief where every factual sentence carries
inline refs of the form [ref:chunk_id]. Only claims that passed grounding are
available to the writer; if a value is not in the sources it cannot appear.
"""

from __future__ import annotations

import json
import sqlite3

from .. import config, llm, schema
from ..audit import append_entry

NOTICE = (
    "Not investment advice. This brief is generated by an instrumented "
    "pipeline; every factual sentence carries a source reference and a "
    "tamper-evident audit entry."
)


def _refs(claims: list[dict]) -> str:
    seen = []
    for c in claims:
        ref = f"[ref:{c['chunk_id']}]"
        if ref not in seen:
            seen.append(ref)
    return " ".join(seen)


def write_offline(checks: list[dict]) -> str:
    lines = [NOTICE, ""]
    order = {t: i for i, t in enumerate(schema.CLAIM_TYPES)}
    for check in sorted(checks, key=lambda c: order.get(c["claim_type"], 99)):
        label = schema.LABELS[check["claim_type"]]
        values = check["detail"]["values"]
        if check["status"] == "agreement":
            n = check["detail"]["source_count"]
            lines.append(
                f"{label} is reported as {check['agreed_value']} by {n} sources "
                f"{_refs(values[0]['claims'])}."
            )
        elif check["status"] == "single_source":
            lines.append(
                f"{label} is reported as {check['agreed_value']} by a single source "
                f"{_refs(values[0]['claims'])}."
            )
        else:
            parts = []
            for v in values:
                parts.append(f"{v['value']} {_refs(v['claims'])}")
            lines.append(
                f"{label} is contradicted across sources: " + " versus ".join(parts) + "."
            )
    return "\n".join(lines)


BRIEF_SYSTEM = """You write a short due-diligence brief from cross-checked, grounded claims.
Rules:
- Use ONLY the values provided. Never add numbers, dates, or names that are not in the claim list.
- Every sentence that states a fact MUST end with the source refs given for that claim, verbatim, in the form [ref:chunk_id].
- When a claim is contradicted, state both values with their respective refs.
- Open with this exact notice line: %s
- Plain text, no markdown headers.""" % NOTICE


def write_llm(checks: list[dict]) -> tuple[str, dict]:
    payload = []
    for check in checks:
        payload.append({
            "claim_type": check["claim_type"],
            "status": check["status"],
            "confidence": check["confidence"],
            "values": [
                {"value": v["value"], "sources": v["sources"],
                 "refs": _refs(v["claims"])}
                for v in check["detail"]["values"]
            ],
        })
    text, usage = llm.complete(BRIEF_SYSTEM, json.dumps(payload, indent=2), max_tokens=2048)
    if NOTICE not in text:
        text = NOTICE + "\n\n" + text
    return text.strip(), usage


def run_brief(conn: sqlite3.Connection, run_id: str, checks: list[dict], span) -> str:
    if config.offline_mode():
        brief = write_offline(checks)
        span.set("backend", "offline-template")
    else:
        brief, usage = write_llm(checks)
        span.add_usage(usage)
        span.set("backend", "anthropic:" + config.model_name())
    append_entry(conn, run_id, "brief_written", {
        "chars": len(brief),
        "claim_types": [c["claim_type"] for c in checks],
    })
    span.set("brief_chars", len(brief))
    return brief
